                    f"{type(values)}._reduce will require a `keepdims` parameter "
                    "in the future",
                    FutureWarning,
                    stacklevel=find_stack_level(),
                )
                result = values._reduce(name, skipna=skipna, **kwds)
                return np.array([result])
        else:
            return op(values, axis=axis, skipna=skipna, **kwds)

