def tokenize(string):
    """Tokenize `string`. There are only two token types - strings
            and escaped characters:

            tokenize(r'foo\=bar\\baz')
            => ['foo', Escaped('='), 'bar', Escaped('\\'), 'baz']

            """
    backslash = '\\'
    tokens = ['']
    characters = iter(string)
